/// <summary>
/// The groups of a SELECT statement with 2 tables, before its projection (<c>docs/design.ja.md</c> §5.5). The lambdas
/// of the stage get the key, then the column set of each table. The columns are <see cref="PerRow"/>, so they can be
/// used only inside aggregates, and every item of the projection is <see cref="PerGroup"/> (§4.5).
/// </summary>
/// <typeparam name="TDialect">The SQL dialect.</typeparam>
/// <typeparam name="TMode">Whether the statement can be run: <see cref="Executable"/> or <see cref="SqlOnly"/>.</typeparam>
/// <typeparam name="TKey">The key as the lambdas get it: an expression, or a tuple of expressions.</typeparam>
/// <typeparam name="T1">The column set of table 1.</typeparam>
/// <typeparam name="T2">The column set of table 2.</typeparam>
public abstract class SelectGroupSource<TDialect, TMode, TKey, T1, T2>
    where TDialect : IDialect
    where TMode : ExecutionMode
{
    private protected SelectGroupSource(IStatementRunner? session, SelectState state, TKey key, T1 v1, T2 v2)
    {
        Session = session;
        State = state;
        Key = key;
        V1 = v1;
        V2 = v2;
    }

    private protected IStatementRunner? Session { get; }

    private protected SelectState State { get; }

    private protected TKey Key { get; }

    private protected T1 V1 { get; }

    private protected T2 V2 { get; }

    /// <summary>
    /// Sets the projection: <c>SELECT …</c>. The projection is a key, an aggregate, an expression of them, or a result
    /// type's group projection (<c>docs/design.ja.md</c> §4.5, §5.6).
    /// </summary>
    /// <typeparam name="TResult">The type that each row is read as.</typeparam>
    /// <param name="projection">The projection, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectGroupedProjected<TDialect, TMode, TResult, TKey, T1, T2> Select<TResult>(
        Func<TKey, T1, T2, IProjection<TResult, PerGroup>> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        IProjection<TResult, PerGroup> selected = projection(Key, V1, V2);
        return new(Session, State.WithProjection(selected, distinct: false), selected, Key, V1, V2);
    }

    /// <summary>
    /// Sets the projection of one expression: <c>SELECT DISTINCT a</c> (<c>docs/design.ja.md</c> §5.7). The
    /// <c>OrderBy</c> that may follow gets the selected item.
    /// </summary>
    /// <typeparam name="TResult">The type that each row is read as.</typeparam>
    /// <param name="projection">The expression, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectDistinctProjected<TDialect, TMode, TResult, PerGroup, DistinctItem<TResult, PerGroup>> SelectDistinct<TResult>(
        Func<TKey, T1, T2, IExpr<TResult, PerGroup>> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        IExpr<TResult, PerGroup> selected = projection(Key, V1, V2);
        return new(Session, State.WithProjection(selected, distinct: true), selected, new DistinctItem<TResult, PerGroup>(1));
    }

    /// <summary>
    /// Sets the projection of a whole row or a result type's projection: <c>SELECT DISTINCT …</c>
    /// (<c>docs/design.ja.md</c> §5.7). It has no <c>OrderBy</c>; select a tuple of expressions to order the rows.
    /// </summary>
    /// <typeparam name="TResult">The type that each row is read as.</typeparam>
    /// <param name="projection">The projection, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectDistinctRows<TDialect, TMode, TResult, PerGroup> SelectDistinct<TResult>(
        Func<TKey, T1, T2, IProjection<TResult, PerGroup>> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        IProjection<TResult, PerGroup> selected = projection(Key, V1, V2);
        return new(Session, State.WithProjection(selected, distinct: true), selected);
    }

    /// <summary>
    /// Sets the projection as a tuple of 2 items: <c>SELECT a, b, …</c>. Every item is <see cref="PerGroup"/>
    /// (<c>docs/design.ja.md</c> §5.6).
    /// </summary>
