            selected,
            (
                new DistinctItem<TItem1, PerGroup>(1),
                new DistinctItem<TItem2, PerGroup>(2),
                new DistinctItem<TItem3, PerGroup>(3),
                new DistinctItem<TItem4, PerGroup>(4),
