/// <summary>
/// The groups of a SELECT statement with 8 tables, before its projection (<c>docs/design.ja.md</c> §5.5). The lambdas
/// of the stage get the key, then the column set of each table. The columns are <see cref="PerRow"/>, so they can be
/// used only inside aggregates, and every item of the projection is <see cref="PerGroup"/> (§4.5).
/// </summary>
/// <typeparam name="TDialect">The SQL dialect.</typeparam>
/// <typeparam name="TMode">Whether the statement can be run: <see cref="Executable"/> or <see cref="SqlOnly"/>.</typeparam>
/// <typeparam name="TKey">The key as the lambdas get it: an expression, or a tuple of expressions.</typeparam>
/// <typeparam name="T1">The column set of table 1.</typeparam>
/// <typeparam name="T2">The column set of table 2.</typeparam>
/// <typeparam name="T3">The column set of table 3.</typeparam>
/// <typeparam name="T4">The column set of table 4.</typeparam>
/// <typeparam name="T5">The column set of table 5.</typeparam>
/// <typeparam name="T6">The column set of table 6.</typeparam>
/// <typeparam name="T7">The column set of table 7.</typeparam>
/// <typeparam name="T8">The column set of table 8.</typeparam>
public abstract class SelectGroupSource<TDialect, TMode, TKey, T1, T2, T3, T4, T5, T6, T7, T8>
    where TDialect : IDialect
    where TMode : ExecutionMode
{
    private protected SelectGroupSource(
        IStatementRunner? session,
        SelectState state,
        TKey key,
        T1 v1,
        T2 v2,
        T3 v3,
        T4 v4,
        T5 v5,
        T6 v6,
        T7 v7,
        T8 v8
    )
    {
        Session = session;
        State = state;
        Key = key;
        V1 = v1;
        V2 = v2;
        V3 = v3;
        V4 = v4;
        V5 = v5;
        V6 = v6;
        V7 = v7;
        V8 = v8;
    }

    private protected IStatementRunner? Session { get; }

    private protected SelectState State { get; }

    private protected TKey Key { get; }

    private protected T1 V1 { get; }

    private protected T2 V2 { get; }

    private protected T3 V3 { get; }

    private protected T4 V4 { get; }

    private protected T5 V5 { get; }

    private protected T6 V6 { get; }

    private protected T7 V7 { get; }

    private protected T8 V8 { get; }

    /// <summary>
    /// Sets the projection: <c>SELECT …</c>. The projection is a key, an aggregate, an expression of them, or a result
    /// type's group projection (<c>docs/design.ja.md</c> §4.5, §5.6).
    /// </summary>
    /// <typeparam name="TResult">The type that each row is read as.</typeparam>
    /// <param name="projection">The projection, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectGroupedProjected<TDialect, TMode, TResult, TKey, T1, T2, T3, T4, T5, T6, T7, T8> Select<TResult>(
        Func<TKey, T1, T2, T3, T4, T5, T6, T7, T8, IProjection<TResult, PerGroup>> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        IProjection<TResult, PerGroup> selected = projection(Key, V1, V2, V3, V4, V5, V6, V7, V8);
        return new(Session, State.WithProjection(selected, distinct: false), selected, Key, V1, V2, V3, V4, V5, V6, V7, V8);
    }

    /// <summary>
    /// Sets the projection of one expression: <c>SELECT DISTINCT a</c> (<c>docs/design.ja.md</c> §5.7). The
    /// <c>OrderBy</c> that may follow gets the selected item.
    /// </summary>
    /// <typeparam name="TResult">The type that each row is read as.</typeparam>
    /// <param name="projection">The expression, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectDistinctProjected<TDialect, TMode, TResult, PerGroup, DistinctItem<TResult, PerGroup>> SelectDistinct<TResult>(
        Func<TKey, T1, T2, T3, T4, T5, T6, T7, T8, IExpr<TResult, PerGroup>> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        IExpr<TResult, PerGroup> selected = projection(Key, V1, V2, V3, V4, V5, V6, V7, V8);
        return new(Session, State.WithProjection(selected, distinct: true), selected, new DistinctItem<TResult, PerGroup>(1));
    }

    /// <summary>
    /// Sets the projection of a whole row or a result type's projection: <c>SELECT DISTINCT …</c>
    /// (<c>docs/design.ja.md</c> §5.7). It has no <c>OrderBy</c>; select a tuple of expressions to order the rows.
    /// </summary>
    /// <typeparam name="TResult">The type that each row is read as.</typeparam>
    /// <param name="projection">The projection, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectDistinctRows<TDialect, TMode, TResult, PerGroup> SelectDistinct<TResult>(
        Func<TKey, T1, T2, T3, T4, T5, T6, T7, T8, IProjection<TResult, PerGroup>> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        IProjection<TResult, PerGroup> selected = projection(Key, V1, V2, V3, V4, V5, V6, V7, V8);
        return new(Session, State.WithProjection(selected, distinct: true), selected);
    }

    /// <summary>
    /// Sets the projection as a tuple of 2 items: <c>SELECT a, b, …</c>. Every item is <see cref="PerGroup"/>
    /// (<c>docs/design.ja.md</c> §5.6).
    /// </summary>
    /// <typeparam name="TItem1">The type of item 1.</typeparam>
    /// <typeparam name="TItem2">The type of item 2.</typeparam>
    /// <param name="projection">The items, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectGroupedProjected<TDialect, TMode, (TItem1, TItem2), TKey, T1, T2, T3, T4, T5, T6, T7, T8> Select<TItem1, TItem2>(
        Func<TKey, T1, T2, T3, T4, T5, T6, T7, T8, (IProjection<TItem1, PerGroup>, IProjection<TItem2, PerGroup>)> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        (IProjection<TItem1, PerGroup>, IProjection<TItem2, PerGroup>) items = projection(Key, V1, V2, V3, V4, V5, V6, V7, V8);
        var selected = new TupleProjection<TItem1, TItem2, PerGroup>(items.Item1, items.Item2);
        return new(Session, State.WithProjection(selected, distinct: false), selected, Key, V1, V2, V3, V4, V5, V6, V7, V8);
    }

    /// <summary>
    /// Sets the projection as a tuple of 2 expressions: <c>SELECT DISTINCT a, b, …</c> (<c>docs/design.ja.md</c>
    /// §5.7). The <c>OrderBy</c> that may follow gets the selected items.
    /// </summary>
    /// <typeparam name="TItem1">The type of item 1.</typeparam>
    /// <typeparam name="TItem2">The type of item 2.</typeparam>
    /// <param name="projection">The expressions, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectDistinctProjected<
        TDialect,
        TMode,
        (TItem1, TItem2),
        PerGroup,
        (DistinctItem<TItem1, PerGroup>, DistinctItem<TItem2, PerGroup>)
    > SelectDistinct<TItem1, TItem2>(Func<TKey, T1, T2, T3, T4, T5, T6, T7, T8, (IExpr<TItem1, PerGroup>, IExpr<TItem2, PerGroup>)> projection)
    {
        ArgumentNullException.ThrowIfNull(projection);
        (IExpr<TItem1, PerGroup>, IExpr<TItem2, PerGroup>) items = projection(Key, V1, V2, V3, V4, V5, V6, V7, V8);
        var selected = new TupleProjection<TItem1, TItem2, PerGroup>(items.Item1, items.Item2);
        return new(
            Session,
            State.WithProjection(selected, distinct: true),
            selected,
            (new DistinctItem<TItem1, PerGroup>(1), new DistinctItem<TItem2, PerGroup>(2))
        );
    }

    /// <summary>
    /// Sets the projection as a tuple of 2 items, some of them whole rows: <c>SELECT DISTINCT …</c>
    /// (<c>docs/design.ja.md</c> §5.7). It has no <c>OrderBy</c>; select a tuple of expressions to order the rows.
    /// </summary>
    /// <typeparam name="TItem1">The type of item 1.</typeparam>
    /// <typeparam name="TItem2">The type of item 2.</typeparam>
    /// <param name="projection">The items, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectDistinctRows<TDialect, TMode, (TItem1, TItem2), PerGroup> SelectDistinct<TItem1, TItem2>(
        Func<TKey, T1, T2, T3, T4, T5, T6, T7, T8, (IProjection<TItem1, PerGroup>, IProjection<TItem2, PerGroup>)> projection
    )
    {
        ArgumentNullException.ThrowIfNull(projection);
        (IProjection<TItem1, PerGroup>, IProjection<TItem2, PerGroup>) items = projection(Key, V1, V2, V3, V4, V5, V6, V7, V8);
        var selected = new TupleProjection<TItem1, TItem2, PerGroup>(items.Item1, items.Item2);
        return new(Session, State.WithProjection(selected, distinct: true), selected);
    }

    /// <summary>
    /// Sets the projection as a tuple of 3 items: <c>SELECT a, b, …</c>. Every item is <see cref="PerGroup"/>
    /// (<c>docs/design.ja.md</c> §5.6).
    /// </summary>
    /// <typeparam name="TItem1">The type of item 1.</typeparam>
    /// <typeparam name="TItem2">The type of item 2.</typeparam>
    /// <typeparam name="TItem3">The type of item 3.</typeparam>
    /// <param name="projection">The items, from the key and the column sets.</param>
    /// <returns>The statement.</returns>
    public SelectGroupedProjected<TDialect, TMode, (TItem1, TItem2, TItem3), TKey, T1, T2, T3, T4, T5, T6, T7, T8> Select<TItem1, TItem2, TItem3>(
